using System;
using System.IO;
using System.Collections.Generic;
using System.Web.Script.Serialization;
using Recovered.Gameplay;
public class WorldPhase4220261013Verify {
 static uint Bits(float f){return BitConverter.ToUInt32(BitConverter.GetBytes(f),0);}
 public static int Main(string[] args){var json=new JavaScriptSerializer();json.MaxJsonLength=256*1024*1024;var data=World19Support.Obj(json.DeserializeObject(World19Support.Input(args[0])));var regions=World19Support.Arr(data["regions"]);int cases=0,checks=0,failures=0;var errors=new List<object>();foreach(object v in World19Support.Arr(data["cases"])){var row=World19Support.Obj(v);var expected=World19Support.Obj(row["expected"]);var bad=new List<string>();try{var m=World19Support.Setup(regions,row);foreach(object patch in World19Support.Arr(data["common"])){var p=World19Support.Obj(patch);uint at=World19Support.U(p["address"]);byte[] b=Convert.FromBase64String((string)p["data"]);for(int i=0;i<b.Length;i++)m.Byte(at+(uint)i,b[i]);}var trace=new List<object>();Func<SoundSetupImage,uint,uint[],uint> service=delegate(SoundSetupImage image,uint address,uint[] values){trace.Add(new object[]{address,values});if(address==0x600260){image.Word(values[0]+0x2a8,0x10178000);return 0;}uint e=values[0],r=values[1],p=values[2];if(World19Support.Yes(row,"mutateParticle")){image.Word(p,Bits(4));image.Word(p+16,Bits(-3));}if(World19Support.Yes(row,"mutateEmitter")){image.Word(e+0x19c,Bits(6));image.Word(e+0x1ac,Bits(7));}if(World19Support.Yes(row,"mutateRecord")){image.Byte(r+0x410,3);image.Word(r+0x414,Bits(0.75f));}if(World19Support.Yes(row,"publishEarly"))image.Word(r+0x2a8,0x10179000);if(World19Support.Yes(row,"mutateType"))image.Byte(r+0x2e,7);return 0;};uint result=PtlSphericalInitializer.Initialize(m,World19Support.U(row["emitter"]),World19Support.U(row["record"]),World19Support.U(row["time"]),service);++checks;if(result!=World19Support.U(expected["result"]))bad.Add("original particle pointer return");++checks;if(!World19Support.Equal(trace,expected["trace"]))bad.Add("ordered attribute/publication service boundary");++checks;if(World19Support.Hash(m,regions)!=(string)expected["sha256"])bad.Add("complete spherical initializer image");}catch(Exception e){bad.Add(e.ToString());}if(bad.Count!=0){failures++;if(errors.Count<12)errors.Add(new{cases,bad});}cases++;}string report=json.Serialize(new{cases,checks,mismatches=failures,errors,binarySha256=data["binarySha256"]});File.WriteAllText(args[1],report);Console.WriteLine(report);return failures==0?0:1;}
}
